type FileItem = { id:string|number; name:string; type:string; size:string; views:number; earned:number; status:string; color:string; updated:string; link?:string|null };
type Toast = {id:number; text:string};
type RazorpayResponse = { razorpay_order_id?: string; razorpay_subscription_id?: string; razorpay_payment_id?: string; razorpay_signature?: string };
type RazorpayOptions = { key:string; amount?:number; currency:string; name:string; description:string; order_id?:string; subscription_id?:string; handler:(response:RazorpayResponse)=>Promise<void> };
type RazorpayConstructor = new (options:RazorpayOptions) => { open:()=>void };
type EventRecord = Awaited<ReturnType<typeof getEvents>>["events"][number];
type CreatorTicket = Awaited<ReturnType<typeof getCreatorTickets>>["tickets"][number];
type AdminTicket = Awaited<ReturnType<typeof getAdminTickets>>["tickets"][number];
type AdminReport = Awaited<ReturnType<typeof getAdminReports>>["reports"][number];
type AdminEvent = Awaited<ReturnType<typeof getAdminEvents>>["events"][number];
type AdminUser = Awaited<ReturnType<typeof getAdminUsers>>["users"][number];
type AdminSubscription = Awaited<ReturnType<typeof getAdminSubscriptions>>["subscriptions"][number];
type AdminPayment = Awaited<ReturnType<typeof getAdminPayments>>["payments"][number];

const userNav = [["Overview","/user/dashboard","◫"],["Upload","/user/upload","↑"],["My Files","/user/files","▱"],["Analytics","/user/analytics","⌁"],["Earnings","/user/earnings","$"],["Withdraw","/user/withdraw","↗"],["Premium","/user/premium","★"],["Events","/user/events","♢"],["Tickets","/user/tickets","?"],["Bots & API","/user/bots","⌘"],["Settings","/user/settings","⚙"]];
const adminNav = [["Command Center","/admin/dashboard","◫"],["Users","/admin/users","♙"],["Files","/admin/files","▱"],["Revenue","/admin/revenue","$"],["Withdrawals","/admin/withdrawals","↗"],["Reports & DMCA","/admin/reports","!"],["Support","/admin/tickets","?"],["Events","/admin/events","♢"],["Settings","/admin/settings","⚙"]];

function routeNow(){ return typeof window === "undefined" ? "/" : window.location.pathname; }
function money(n:number){ return new Intl.NumberFormat("en-US",{style:"currency",currency:"USD"}).format(n); }
function toastGlobal(message:string){if(typeof window!=="undefined")window.alert(message)}
function importRazorpay():Promise<RazorpayConstructor|null>{return new Promise(resolve=>{const existing=(window as Window & {Razorpay?:RazorpayConstructor}).Razorpay;if(existing){resolve(existing);return}const script=document.createElement("script");script.src="https://checkout.razorpay.com/v1/checkout.js";script.onload=()=>resolve((window as Window & {Razorpay?:RazorpayConstructor}).Razorpay||null);script.onerror=()=>resolve(null);document.body.appendChild(script)})}
async function verifyPayment(token:string,subscriptionId:string,response:RazorpayResponse){return verifySubscriptionPayment(token,{subscriptionId,razorpayOrderId:response.razorpay_order_id,razorpaySubscriptionId:response.razorpay_subscription_id,razorpayPaymentId:response.razorpay_payment_id,razorpaySignature:response.razorpay_signature})}

export default function NightBoxApp(){
  const [route,setRoute]=useState(()=>routeNow()); const [toasts,setToasts]=useState<Toast[]>([]); const [files,setFiles]=useState<FileItem[]>([]); const [token,setToken]=useState(()=>typeof window!=="undefined"?localStorage.getItem("nightbox-token")||"":""); const [adminAuth,setAdminAuth]=useState(()=>typeof window!=="undefined"&&sessionStorage.getItem("nightbox-admin")==="1"); const [menu,setMenu]=useState(false);
  useEffect(()=>{const h=()=>{setRoute(routeNow());setMenu(false)};window.addEventListener("popstate",h);return()=>window.removeEventListener("popstate",h)},[]);
  
// eslint-disable-next-line react-hooks/set-state-in-effect
useEffect(()=>{if(!token){setFiles([]);return}getCreatorVideos(token).then(({videos})=>{const next=videos.map(v=>({id:v.id,name:v.title,type:"VIDEO",size:v.fileSize?`${(v.fileSize/1024/1024).toFixed(1)} MB`:"Backend record",views:v.eligibleViews,earned:v.earningsMicros/1000000,status:v.status,color:"#2563eb",updated:new Date(v.createdAt).toLocaleDateString(),link:v.link}));setFiles(next)}).catch(()=>setFiles([]))},[token]);
  const go=(p:string)=>{history.pushState({},"",p);setRoute(p);setMenu(false);window.scrollTo({top:0,behavior:"smooth"})};
  const toast=(text:string)=>{const id=Date.now();setToasts(t=>[...t,{id,text}]);setTimeout(()=>setToasts(t=>t.filter(x=>x.id!==id)),2800)};
  const saveFiles=(next:FileItem[])=>{setFiles(next)};
  const setSession=(nextToken:string)=>{setToken(nextToken);localStorage.setItem("nightbox-token",nextToken)};
  let content;if(route.startsWith("/admin"))content=<AdminApp route={route} go={go} auth={adminAuth} setAuth={setAdminAuth} toast={toast}/>;else if(route.startsWith("/user"))content=<UserApp route={route} go={go} files={files} saveFiles={saveFiles} toast={toast} token={token}/>;else if(route.startsWith("/auth"))content=<LiveAuthPage route={route} go={go} toast={toast} setSession={setSession}/>;else content=<PublicSite route={route} go={go} menu={menu} setMenu={setMenu} toast={toast}/>;
  return <>{content}<div className="toast-stack">{toasts.map(t=><div className="toast" key={t.id}>✓ {t.text}</div>)}</div></>;
}

function Brand({dark=false,go}:{dark?:boolean,go:(p:string)=>void}){return <button className={`brand ${dark?"brand-dark":""}`} onClick={()=>go("/")}><span className="brand-mark"><i/><i/></span><span>Night<span>Box</span></span></button>}
function Pill({children,tone="blue"}:{children:React.ReactNode,tone?:string}){return <span className={`pill pill-${tone}`}>{children}</span>}
function Metric({label,value,delta,icon}:{label:string,value:string,delta?:string,icon:string}){return <div className="metric card"><div className="metric-top"><span className="metric-icon">{icon}</span>{delta&&<Pill tone={delta.startsWith("-")?"red":"green"}>{delta}</Pill>}</div><strong>{value}</strong><span>{label}</span></div>}

function PublicSite({route,go,menu,setMenu,toast}:{route:string,go:(p:string)=>void,menu:boolean,setMenu:(v:boolean)=>void,toast:(s:string)=>void}){
  const pages:Record<string,React.ReactNode>={"/":<Home go={go}/>,"/features":<Features go={go}/>,"/events":<Events/>,"/about":<About go={go}/>,"/contact":<Contact toast={toast}/>,"/faq":<FAQ/>,"/terms":<Legal kind="Terms of Service"/>,"/privacy":<Legal kind="Privacy Policy"/>,"/dmca":<Legal kind="DMCA Policy"/>,"/cookies":<Legal kind="Cookie Policy"/>};
  return <div className="public-shell"><header className="public-header"><Brand go={go}/><nav className={menu?"open":""}>{[["Features","/features"],["Events","/events"],["About","/about"],["Contact","/contact"],["FAQ","/faq"]].map(x=><button key={x[1]} onClick={()=>go(x[1])}>{x[0]}</button>)}<button className="btn btn-dark nav-login" onClick={()=>go("/auth/login")}>Sign in</button><button className="btn btn-primary" onClick={()=>go("/user/dashboard")}>Dashboard</button></nav><button className="hamb" onClick={()=>setMenu(!menu)}>☰</button></header>{pages[route]||<NotFound go={go}/>}<Footer go={go}/></div>
}
