function FeatureCard({icon,title,text,color}:{icon:string,title:string,text:string,color:string}){return <article className={`feature-card fc-${color}`}><span className="feature-icon">{icon}</span><h3>{title}</h3><p>{text}</p><a>Explore feature →</a></article>}
function Step({n,title,text}:{n:string,title:string,text:string}){return <article className="step"><b>{n}</b><span/><h3>{title}</h3><p>{text}</p></article>}
function Features({go}:{go:(p:string)=>void}){const groups:[string,string,string[]][]=[["Cloud storage","Keep every creator video in one dependable workspace.",["Multipart video uploads up to 4 GB","Creator-owned video records","Fast CDN delivery","Video upload and playback"]],["Sharing controls","Publish clean links with backend view checks.",["Creator video links","Server-side view authorization","Bunny Stream delivery","Social sharing support"]],["Creator monetization","Turn qualified attention into transparent earnings.",["Configurable CPM rules","File-level revenue","Server-side earning ledger","UPI, bank and PayPal payouts"]],["Performance analytics","Know exactly how every qualified view performs.",["Qualified views and earnings","Country-level CPM reporting","Creator withdrawal history","Admin revenue controls"]],["Safety & compliance","Built-in tools for responsible distribution.",["Traffic quality checks","Hashed IP and viewer records","Duplicate-view filters","Account and file moderation"]],["Support & automation","Get help and move faster with integrations.",["Telegram upload bots","Creator-scoped API keys","Bot event history","Revocable credentials"]]];return <><PageHero eyebrow="NIGHTBOX FEATURES" title="A complete operating system for shared files." text="Powerful enough for growing creator businesses. Clear enough to use from the first upload."/><section className="section feature-page-grid">{groups.map((g,i)=><article className="detail-card" key={g[0]}><span>0{i+1}</span><h2>{g[0]}</h2><p>{g[1]}</p><ul>{g[2].map((x:string)=><li key={x}>✓ {x}</li>)}</ul></article>)}</section><section className="mini-cta"><h2>Ready to move your files forward?</h2><button className="btn btn-primary" onClick={()=>go("/auth/register")}>Start for free →</button></section></>}
	function Events(){const [events,setEvents]=useState<EventRecord[]>([]);useEffect(()=>{getEvents().then(x=>setEvents(Array.isArray(x.events)?x.events:[])).catch(()=>setEvents([]))},[]);return <><PageHero eyebrow="EVENTS HUB" title="Creator events" text="Active campaigns published by NightBox operations."/><section className="section"><div className="event-grid">{events.length?events.map(event=><article className="card detail-card" key={event.id}><span>{event.startsAt?new Date(event.startsAt).toLocaleDateString():"ACTIVE"}</span><h2>{event.title}</h2><p>{event.description}</p>{event.rewardNote&&<small>{event.rewardNote}</small>}</article>):<div className="card empty-state"><h2>No active events</h2><p>New events will appear here when published by NightBox operations.</p></div>}</div></section></>}
function About({go}:{go:(p:string)=>void}){return <><PageHero eyebrow="ABOUT NIGHTBOX" title="Creators deserve more than a download button." text="NightBox is building a safer, clearer way to distribute digital work and understand its real reach."/><section className="section"><div className="story"><div><Pill>OUR MISSION</Pill><h2>Make digital distribution work for the people who create value.</h2></div><div><p>Traditional file hosting treats a creator work like anonymous storage. NightBox treats every shared file as a living digital asset with context, protection, analytics and earning potential.</p><p>We are focused on thoughtful product design, transparent reporting and infrastructure that stays dependable when a link travels far.</p><button className="btn btn-dark" onClick={()=>go("/auth/register")}>Join NightBox →</button></div></div></section></>}
function Contact({toast}:{toast:(s:string)=>void}){const submit=async(e:React.FormEvent<HTMLFormElement>)=>{e.preventDefault();const form=new FormData(e.currentTarget);try{await sendContactMessage({name:String(form.get("name")),email:String(form.get("email")),subject:String(form.get("subject")),message:String(form.get("message"))});toast("Message received by NightBox support");e.currentTarget.reset()}catch(error){toast(error instanceof Error?error.message:"Unable to send message")}};return <><PageHero eyebrow="CONTACT" title="Let’s solve it together." text="Questions, content reports, partnerships or support—we’ll route your message to the right team."/><section className="section contact-grid"><div><h2>Choose the right channel</h2>{[["General support","support@nightbox.cloud"],["Legal & DMCA","legal@nightbox.cloud"],["Advertising","partners@nightbox.cloud"]].map(x=><div className="contact-line" key={x[0]}><span>↗</span><div><b>{x[0]}</b><small>{x[1]}</small></div></div>)}</div><form className="form-card" onSubmit={submit}><div className="two"><label>Name<input name="name" required placeholder="Your full name"/></label><label>Email<input name="email" required type="email" placeholder="you@example.com"/></label></div><label>Subject<input name="subject" required placeholder="What is this about?"/></label><label>Message<textarea name="message" required rows={6} placeholder="Tell us how we can help…"/></label><button className="btn btn-primary" type="submit">Send message →</button></form></section></>}
function FAQ(){const [open,setOpen]=useState(0);const q=[["What is NightBox?","NightBox is a creator-focused cloud platform for storing, sharing and monetizing creator videos."],["Which file types can I upload?","Creator video uploads up to 4 GB are supported through the connected backend and Telegram upload services."],["How are earnings calculated?","Revenue is based on eligible views. The applicable CPM is selected server-side from the viewer country and locked when the view qualifies."],["What is the minimum withdrawal?","The minimum withdrawal threshold is configured by operations and enforced by the backend."],["Can I protect a share link?","Share links pass through backend authorization and view-quality checks. Video delivery depends on the configured Bunny Stream service."],["How does the Telegram bot work?","Users create a revocable API key from Bots & API, connect the upload bot and manage remote uploads from their dashboard."]];return <><PageHero eyebrow="HELP CENTER" title="Answers without the runaround." text="Clear guidance on accounts, files, monetization, security and payouts."/><section className="section faq-list">{q.map((x,i)=><button onClick={()=>setOpen(open===i?-1:i)} className={open===i?"active":""} key={x[0]}><span>{x[0]}</span><b>{open===i?"−":"+"}</b>{open===i&&<p>{x[1]}</p>}</button>)}</section></>}
function DmcaForm(){const [busy,setBusy]=useState(false);const [sent,setSent]=useState(false);const submit=async(e:React.FormEvent<HTMLFormElement>)=>{e.preventDefault();setBusy(true);const form=new FormData(e.currentTarget);try{await submitDmcaReport({name:String(form.get("name")),email:String(form.get("email")),videoUrl:String(form.get("videoUrl")),reason:String(form.get("reason"))});setSent(true);e.currentTarget.reset()}catch(error){toastGlobal(error instanceof Error?error.message:"Unable to submit report")}finally{setBusy(false)}};return <div className="card form-card"><h2>Submit a DMCA report</h2><p>Use this form for a specific infringement notice. Reports are reviewed by the trust and safety team.</p>{sent&&<p className="success-copy">Report received. Our team will review it.</p>}<form onSubmit={submit}><div className="two"><label>Name<input name="name" required/></label><label>Email<input name="email" required type="email"/></label></div><label>Video or link<input name="videoUrl" required type="url" placeholder="https://..."/></label><label>Reason<textarea name="reason" required rows={4}/></label><button className="btn btn-primary" disabled={busy}>{busy?"Submitting…":"Submit report →"}</button></form></div>}
function Legal({kind}:{kind:string}){const all:Record<string,string[]>={"Terms of Service":["Using NightBox","Your account and content","Storage and availability","Creator revenue program","Withdrawals and adjustments","Acceptable use","Suspension and termination"],"Privacy Policy":["Information we collect","How information is used","Sharing and service providers","Data retention","Your rights","Security measures","International processing"],"DMCA Policy":["Reporting infringement","Required notice information","Counter-notice process","Three-strike policy","Restoration timeline","Misrepresentation","Contacting our legal team"],"Cookie Policy":["Essential cookies","Preferences","Analytics","Advertising","Managing consent","Retention","Policy updates"]};const blocks=all[kind]||[];return <><PageHero eyebrow="LEGAL · UPDATED AUGUST 2026" title={kind} text={`This ${kind.toLowerCase()} explains the standards that keep NightBox clear, safe and dependable.`}/>{kind==="DMCA Policy"&&<section className="section"><DmcaForm/></section>}<section className="section legal-layout"><aside>{blocks.map((x,i)=><a key={x}>0{i+1} {x}</a>)}</aside><article>{blocks.map((x,i)=><section key={x}><h2>{i+1}. {x}</h2><p>NightBox is designed to provide secure file storage, controlled sharing, analytics and creator monetization. By using the service, you agree to provide accurate information, respect intellectual property rights and avoid fraudulent or harmful activity.</p><p>Operational limits, eligibility and processing timelines are shown clearly inside the product. We may review reports, restrict content or hold transactions when necessary to protect users, advertisers and the integrity of the platform.</p></section>)}</article></section></>}
function PageHero({eyebrow,title,text}:{eyebrow:string,title:string,text:string}){return <section className="page-hero"><Pill tone="orange">{eyebrow}</Pill><h1>{title}</h1><p>{text}</p></section>}
function Footer({go}:{go:(p:string)=>void}){return <footer><div className="footer-main"><div><Brand dark go={go}/><p>Secure cloud delivery, meaningful analytics and transparent creator earnings.</p><span>support@nightbox.cloud</span></div><div><b>Product</b><button onClick={()=>go("/features")}>Features</button><button onClick={()=>go("/events")}>Events</button><button onClick={()=>go("/user/dashboard")}>Dashboard</button></div><div><b>Resources</b><button onClick={()=>go("/faq")}>FAQ</button><button onClick={()=>go("/contact")}>Contact</button><button onClick={()=>go("/admin/login")}>Admin portal</button></div><div><b>Legal</b><button onClick={()=>go("/terms")}>Terms</button><button onClick={()=>go("/privacy")}>Privacy</button><button onClick={()=>go("/dmca")}>DMCA</button><button onClick={()=>go("/cookies")}>Cookies</button></div></div><div className="footer-bottom"><span>© 2026 NightBox Technologies. All rights reserved.</span><span><i/> Platform status</span></div></footer>}

function LiveAuthPage({route,go,toast,setSession}:{route:string,go:(p:string)=>void,toast:(s:string)=>void,setSession:(token:string)=>void}){
  const isRegister=route.includes("register");
  const forgot=route.includes("forgot");
  const [googleBusy,setGoogleBusy]=useState(false);
  const submit=async(e:React.FormEvent<HTMLFormElement>)=>{
    e.preventDefault();
    if(forgot){toast("Password reset service is not configured");return}
    const data=new FormData(e.currentTarget);
    try{
      const result=isRegister?await register(String(data.get("email")),String(data.get("password"))):await login(String(data.get("email")),String(data.get("password")));
      setSession(result.token);toast(isRegister?"Account created":"Welcome back");setTimeout(()=>go("/user/dashboard"),300)
    }catch(error){toast(error instanceof Error?error.message:"Authentication failed")}
  };
  const signInWithGoogle=async(credential:string)=>{
    setGoogleBusy(true);
    try{
      const result=await loginWithGoogle(credential);
      setSession(result.token);toast("Signed in with Google");setTimeout(()=>go("/user/dashboard"),300)
    }catch(error){toast(error instanceof Error?error.message:"Google sign-in failed")}
    finally{setGoogleBusy(false)}
  };
  return <div className="auth-shell"><div className="auth-art"><Brand dark go={go}/><div className="auth-message"><Pill tone="orange">CREATOR CLOUD</Pill><h1>Your work.<br/>Shared on your terms.</h1><p>Store, distribute and understand every file from one secure workspace.</p></div></div><div className="auth-form-wrap"><button className="back" onClick={()=>go("/")}>← Back to website</button><form className="auth-form" onSubmit={submit}><h2>{forgot?"Reset your password":isRegister?"Create your workspace":"Welcome back"}</h2><p>{forgot?"Password reset service is not configured yet.":isRegister?"Create a secure creator account.":"Sign in to your creator account."}</p>{!forgot&&<><GoogleSignInButton onCredential={signInWithGoogle}/>{googleBusy&&<small className="google-signin-loading">Verifying Google account…</small>}<div className="auth-divider"><span>OR CONTINUE WITH EMAIL</span></div></>}<label>Email address<input name="email" required type="email" placeholder="you@example.com"/></label>{!forgot&&<label>Password<input name="password" required minLength={10} type="password" placeholder="At least 10 characters"/></label>}<button className="btn btn-primary btn-block" type="submit">{forgot?"Request reset":isRegister?"Create account":"Sign in"} →</button>{!forgot&&<small>{isRegister?"Already have an account? ":"New to NightBox? "}<button type="button" onClick={()=>go(isRegister?"/auth/login":"/auth/register")}>{isRegister?"Sign in":"Create account"}</button></small>}</form></div></div>
}

function LiveUpload({files,saveFiles,toast,token}:{files:FileItem[],saveFiles:(x:FileItem[])=>void,toast:(s:string)=>void,token:string}){const [file,setFile]=useState<File|null>(null);const [name,setName]=useState("");const [busy,setBusy]=useState(false);const choose=(next:File|null)=>{setFile(next);if(next&&!name)setName(next.name)};const submit=async()=>{if(!file){toast("Choose a video file first");return}setBusy(true);try{const result=await uploadVideo(file,name,token);const item:FileItem={id:result.videoId,name:name||file.name,type:file.name.split(".").pop()?.toUpperCase()||"VIDEO",size:`${(file.size/1024/1024).toFixed(1)} MB`,views:0,earned:0,status:"Processing",color:"#2563eb",updated:"Just now",link:result.link||result.watchUrl};saveFiles([item,...files]);toast(`Uploaded. Link: ${result.link||result.watchUrl}`);setFile(null);setName("")}catch(error){toast(error instanceof Error?error.message:"Upload failed")}finally{setBusy(false)}};return <><AppTitle eyebrow="FILE DELIVERY" title="Upload a new video"/><div className="upload-layout"><div className="card upload-card"><div className="dropzone"><span>↑</span><h3>{file?.name||"Choose a video file"}</h3><label className="btn btn-dark">Browse files<input type="file" accept="video/*" hidden onChange={e=>choose(e.target.files?.[0]||null)}/></label><small>Uploaded to the connected NightBox backend</small></div><div className="upload-fields"><label>Display name<input value={name} onChange={e=>setName(e.target.value)} placeholder="Video title"/></label><button className="btn btn-primary" disabled={busy||!token} onClick={submit}>{!token?"Sign in to upload":busy?"Uploading…":"Upload to backend →"}</button></div></div></div></>}

function UserApp({route,go,files,saveFiles,toast,token}:{route:string,go:(p:string)=>void,files:FileItem[],saveFiles:(x:FileItem[])=>void,toast:(s:string)=>void,token:string}){return <div className="app-shell"><Sidebar nav={userNav} route={route} go={go} admin={false}/><div className="app-main"><Topbar go={go} admin={false}/><div className="app-content">{route==="/user/dashboard"&&<UserOverview go={go} files={files} token={token}/>} {route==="/user/upload"&&<LiveUpload files={files} saveFiles={saveFiles} toast={toast} token={token}/>} {route==="/user/files"&&<FilesTable files={files} saveFiles={saveFiles} toast={toast} token={token} go={go}/>} {route==="/user/analytics"&&<Analytics token={token}/>} {route==="/user/earnings"&&<Analytics token={token}/>} {route==="/user/withdraw"&&<LiveWithdrawal token={token} toast={toast}/>} {route==="/user/premium"&&<PremiumStatus token={token}/>} {route==="/user/events"&&<LiveUserEvents/>} {route==="/user/tickets"&&<LiveTickets token={token} toast={toast}/>} {route==="/user/bots"&&<LiveBots token={token} toast={toast}/>} {route==="/user/settings"&&<LiveSettings token={token} toast={toast}/>}</div></div></div>}
function Sidebar({nav,route,go,admin}:{nav:string[][],route:string,go:(p:string)=>void,admin:boolean}){const leave=()=>{if(admin){sessionStorage.removeItem("nightbox-admin-token");sessionStorage.removeItem("nightbox-admin")}go(admin?"/admin/login":"/")};return <aside className={`sidebar ${admin?"admin-side":""}`}><Brand dark go={go}/>{admin&&<Pill tone="orange">ADMIN</Pill>}<nav>{nav.map(x=><button className={route===x[1]?"active":""} key={x[1]} onClick={()=>go(x[1])}><i>{x[2]}</i>{x[0]}</button>)}</nav><div className="side-bottom"><div className="storage"><span><b>{admin?"Server capacity":"Your storage"}</b><small>{admin?"Configured in deployment":"Reported by backend"}</small></span><i><em style={{width:"0%"}}/></i></div><button onClick={leave}>↪ {admin?"Lock console":"Back to website"}</button></div></aside>}
function Topbar({go,admin}:{go:(p:string)=>void,admin:boolean}){return <header className="topbar"><div><span>{admin?"NightBox Operations":"Creator workspace"}</span><b>{admin?"Connected":"Connected"}<i/></b></div><div><button className="icon-btn">⌕</button><button className="icon-btn">♢</button><button className="avatar" onClick={()=>go(admin?"/admin/settings":"/user/settings")}>{admin?"OA":"CR"}</button><span className="user-name"><b>{admin?"Operations admin":"Signed-in creator"}</b><small>{admin?"Server-authorized":"Backend account"}</small></span></div></header>}
function AppTitle({eyebrow,title,action}:{eyebrow:string,title:string,action?:React.ReactNode}){return <div className="app-title"><div><span>{eyebrow}</span><h1>{title}</h1></div>{action}</div>}
function LiveTickets({token,toast}:{token:string;toast:(s:string)=>void}){const [rows,setRows]=useState<CreatorTicket[]>([]);const [subject,setSubject]=useState("");const [message,setMessage]=useState("");const load=()=>getCreatorTickets(token).then(x=>setRows(x.tickets)).catch(()=>setRows([]));
// eslint-disable-next-line react-hooks/exhaustive-deps
useEffect(()=>{load()},[token]);const submit=async(e:React.FormEvent)=>{e.preventDefault();try{await createCreatorTicket(token,subject,message);setSubject("");setMessage("");toast("Support ticket created");load()}catch(error){toast(error instanceof Error?error.message:"Unable to create ticket")}};return <><AppTitle eyebrow="SUPPORT" title="Support tickets"/><form className="card compact-form" onSubmit={submit}><h2>Open a ticket</h2><label>Subject<input required value={subject} onChange={e=>setSubject(e.target.value)}/></label><label>Message<textarea required rows={4} value={message} onChange={e=>setMessage(e.target.value)}/></label><button className="btn btn-primary">Send to support</button></form><DataTable headers={["SUBJECT","STATUS","CREATED","UPDATED"]} rows={rows.map(row=>[row.subject,row.status,new Date(row.createdAt).toLocaleDateString(),new Date(row.updatedAt).toLocaleDateString()])}/></>}
function LiveSettings({token,toast}:{token:string;toast:(s:string)=>void}){const [current,setCurrent]=useState("");const [next,setNext]=useState("");const submit=async(e:React.FormEvent)=>{e.preventDefault();try{await updatePassword(token,current,next);setCurrent("");setNext("");toast("Password updated")}catch(error){toast(error instanceof Error?error.message:"Unable to update password")}};return <><AppTitle eyebrow="ACCOUNT" title="Settings"/><form className="card compact-form" onSubmit={submit}><h2>Change password</h2><label>Current password<input required type="password" value={current} onChange={e=>setCurrent(e.target.value)}/></label><label>New password<input required minLength={10} type="password" value={next} onChange={e=>setNext(e.target.value)}/></label><button className="btn btn-primary">Update password</button></form><div className="card empty-state"><h2>Account security</h2><p>Authentication, creator ownership, API keys and earnings permissions are enforced by the backend.</p></div></>}
function LiveAdminTickets({toast}:{toast:(s:string)=>void}){const [rows,setRows]=useState<AdminTicket[]>([]);const load=()=>{const token=sessionStorage.getItem("nightbox-admin-token");if(token)getAdminTickets(token).then(x=>setRows(x.tickets)).catch(()=>setRows([]))};useEffect(load,[]);const update=async(row:AdminTicket)=>{const token=sessionStorage.getItem("nightbox-admin-token");if(!token)return;try{await updateAdminTicket(token,row.id,row.status,row.adminNote||"");toast("Ticket updated");load()}catch(error){toast(error instanceof Error?error.message:"Unable to update ticket")}};return <><AppTitle eyebrow="SUPPORT OPERATIONS" title="Support queue" action={<button className="btn btn-dark" onClick={load}>Refresh</button>}/><DataTable headers={["USER","SUBJECT","MESSAGE","STATUS","ACTION"]} rows={rows.map(row=>[row.email,row.subject,row.message,<select key={row.id} value={row.status} onChange={e=>{row.status=e.target.value;setRows([...rows])}}><option>open</option><option>in_progress</option><option>resolved</option><option>closed</option></select>,<button key={row.id} onClick={()=>update(row)}>Save</button>])}/></>}
	function LiveUserEvents(){const [events,setEvents]=useState<EventRecord[]>([]);useEffect(()=>{getEvents().then(x=>setEvents(Array.isArray(x.events)?x.events:[])).catch(()=>setEvents([]))},[]);return <><AppTitle eyebrow="COMMUNITY" title="Events"/><DataTable headers={["EVENT","DETAILS","REWARD"]} rows={events.map(event=>[event.title,event.description,event.rewardNote||"See event details"])}/>{!events.length&&<div className="card empty-state"><p>No active events are currently published.</p></div>}</>}
function LiveAdminReports({toast}:{toast:(s:string)=>void}){const [rows,setRows]=useState<AdminReport[]>([]);const load=()=>{const token=sessionStorage.getItem("nightbox-admin-token");if(token)getAdminReports(token).then(x=>setRows(x.reports)).catch(()=>setRows([]))};useEffect(load,[]);const update=async(row:AdminReport)=>{const token=sessionStorage.getItem("nightbox-admin-token");if(!token)return;try{await updateAdminReport(token,row.id,row.status,row.adminNote||"");toast("Report updated");load()}catch(error){toast(error instanceof Error?error.message:"Unable to update report")}};return <><AppTitle eyebrow="TRUST & SAFETY" title="Reports and DMCA" action={<button className="btn btn-dark" onClick={load}>Refresh</button>}/><DataTable headers={["REPORTER","REASON","VIDEO","STATUS","ACTION"]} rows={rows.map(row=>[row.reporterEmail,row.reason,row.videoUrl||row.videoId||"Not specified",<select key={row.id} value={row.status} onChange={e=>{row.status=e.target.value;setRows([...rows])}}><option>open</option><option>in_review</option><option>resolved</option><option>rejected</option></select>,<button key={row.id} onClick={()=>update(row)}>Save</button>])}/>{!rows.length&&<div className="card empty-state"><p>No reports are currently pending.</p></div>}</>}
function LiveAdminEvents({toast}:{toast:(s:string)=>void}){const [rows,setRows]=useState<AdminEvent[]>([]);const [title,setTitle]=useState("");const [description,setDescription]=useState("");const load=()=>{const token=sessionStorage.getItem("nightbox-admin-token");if(token)getAdminEvents(token).then(x=>setRows(x.events)).catch(()=>setRows([]))};useEffect(load,[]);const create=async(e:React.FormEvent)=>{e.preventDefault();const token=sessionStorage.getItem("nightbox-admin-token");if(!token)return;try{await createAdminEvent(token,{title,description,active:1});setTitle("");setDescription("");toast("Event published");load()}catch(error){toast(error instanceof Error?error.message:"Unable to publish event")}};const toggle=async(row:AdminEvent)=>{const token=sessionStorage.getItem("nightbox-admin-token");if(!token)return;try{await updateAdminEvent(token,row.id,row.active?0:1);load()}catch(error){toast(error instanceof Error?error.message:"Unable to update event")}};return <><AppTitle eyebrow="COMMUNITY OPERATIONS" title="Events"/><form className="card compact-form" onSubmit={create}><h2>Publish event</h2><label>Title<input required value={title} onChange={e=>setTitle(e.target.value)}/></label><label>Description<textarea required rows={3} value={description} onChange={e=>setDescription(e.target.value)}/></label><button className="btn btn-primary">Publish event</button></form><DataTable headers={["EVENT","DESCRIPTION","STATUS","ACTION"]} rows={rows.map(row=>[row.title,row.description,row.active?"Active":"Hidden",<button key={row.id} onClick={()=>toggle(row)}>{row.active?"Hide":"Publish"}</button>])}/></>}
function LiveAdminSettings(){const [settings,setSettings]=useState<Record<string,string|boolean>|null>(null);useEffect(()=>{const token=sessionStorage.getItem("nightbox-admin-token");if(token)getAdminSettings(token).then(x=>setSettings(x.settings)).catch(()=>setSettings(null))},[]);return <><AppTitle eyebrow="PLATFORM" title="Settings"/><div className="card settings-list">{settings?Object.entries(settings).map(([key,value])=><div className="table-row" key={key}><b>{key}</b><span>{String(value)}</span></div>):<p className="empty-copy">Unable to load platform configuration.</p>}</div><div className="card empty-state"><p>Secrets are intentionally not exposed in the admin UI. Change deployment values through the server environment.</p></div></>}
function LiveWithdrawal({token,toast}:{token:string;toast:(s:string)=>void}){const [data,setData]=useState<{balanceMicros:number;minimumMicros:number;withdrawals:Array<{id:string;amountMicros:number;currency:string;method:string;status:string;requestedAt:string}>}|null>(null);const [amount,setAmount]=useState("");const [method,setMethod]=useState("UPI");const load=()=>getCreatorWithdrawals(token).then(setData).catch(()=>setData(null));
// eslint-disable-next-line react-hooks/exhaustive-deps
useEffect(()=>{load()},[token]);const submit=async(e:React.FormEvent)=>{e.preventDefault();try{await createWithdrawal(token,Math.round(Number(amount)*1000000),method);toast("Withdrawal request submitted for review");setAmount("");load()}catch(error){toast(error instanceof Error?error.message:"Withdrawal failed")}};return <><AppTitle eyebrow="PAYOUTS" title="Withdraw earnings"/><form className="card compact-form" onSubmit={submit}><h2>Request payout</h2><p>Available: {money((data?.balanceMicros||0)/1000000)} · Minimum: {money((data?.minimumMicros||10000000)/1000000)}</p><label>Amount (USD)<input required type="number" min="0" step="0.01" value={amount} onChange={e=>setAmount(e.target.value)}/></label><label>Method<input required value={method} onChange={e=>setMethod(e.target.value)} placeholder="UPI, bank, or PayPal"/></label><button className="btn btn-primary">Submit request</button></form><DataTable headers={["REQUEST","AMOUNT","METHOD","STATUS","REQUESTED"]} rows={(data?.withdrawals||[]).map(row=>[row.id.slice(0,8),money(row.amountMicros/1000000),row.method,row.status,new Date(row.requestedAt).toLocaleDateString()])}/></>}
function LiveBots({token,toast}:{token:string;toast:(s:string)=>void}){const [keys,setKeys]=useState<Array<{id:string;prefix:string;createdAt:string;lastUsedAt:string|null;revokedAt:string|null}>>([]);const [newKey,setNewKey]=useState("");const load=()=>getCreatorApiKeys(token).then(x=>setKeys(x.keys)).catch(()=>setKeys([]));
// eslint-disable-next-line react-hooks/exhaustive-deps
useEffect(()=>{load()},[token]);const create=async()=>{try{const result=await createCreatorApiKey(token);setNewKey(result.key.value);toast("Key created. Copy it now; it will not be shown again.");load()}catch(error){toast(error instanceof Error?error.message:"Unable to create key")}};return <><AppTitle eyebrow="AUTOMATION" title="Bots & API" action={<button className="btn btn-primary" onClick={create}>Create API key</button>}/>{newKey&&<div className="card empty-state"><h2>New creator key</h2><p>Store this securely and configure it as CREATOR_API_KEY for a bot.</p><code>{newKey}</code></div>}<DataTable headers={["KEY","CREATED","LAST USED","STATUS"]} rows={keys.map(key=>[key.prefix,new Date(key.createdAt).toLocaleDateString(),key.lastUsedAt?new Date(key.lastUsedAt).toLocaleString():"Never",key.revokedAt?"Revoked":"Active"])}/></>}
function UserOverview({go,files,token}:{go:(p:string)=>void,files:FileItem[],token:string}){const [analytics,setAnalytics]=useState<{views:number;earningsMicros:number}>({views:0,earningsMicros:0});useEffect(()=>{getCreatorAnalytics(token).then(x=>setAnalytics(x.summary)).catch(()=>{})},[token,files.length]);return <><AppTitle eyebrow="CREATOR WORKSPACE" title="Your workspace" action={<button className="btn btn-primary" onClick={()=>go("/user/upload")}>↑ Upload files</button>}/><div className="metrics"><Metric icon="$" label="Recorded earnings" value={money(analytics.earningsMicros/1000000)}/><Metric icon="◉" label="Verified views" value={analytics.views.toLocaleString()}/><Metric icon="▱" label="Uploaded videos" value={String(files.length)}/><Metric icon="↗" label="Downloads" value="Not tracked"/></div><PremiumStatus token={token}/><div className="card empty-state"><h2>Backend-connected workspace</h2><p>Video records and qualified analytics are loaded from the NightBox backend. Upload a video or share a creator link to begin collecting real data.</p><button className="btn btn-primary" onClick={()=>go("/user/upload")}>Upload a video →</button></div><div className="card recent"><div className="card-head"><div><b>Recent videos</b><span>Records returned by the backend</span></div><button onClick={()=>go("/user/files")}>View all →</button></div>{files.length?<FileRows files={files.slice(0,4)}/>:<p className="empty-copy">No videos uploaded yet.</p>}</div></>}
function PremiumStatus({token}:{token:string}){const [subscription,setSubscription]=useState<{id:string;name:string;status:string;expiresAt:string|null;renewsAt:string|null;cancelledAt?:string|null;videoAdsRemoved:number;allAdsRemoved:number;recurring:number}|null>(null);const [plans,setPlans]=useState<Array<{id:string;name:string;price_minor:number;currency:string;duration_days:number;recurring:number}>>([]);const [busy,setBusy]=useState(false);const load=()=>Promise.all([getSubscription(token),getPlans()]).then(([active,available])=>{setSubscription(active.subscription as typeof subscription);setPlans(available.plans)}).catch(()=>{});
// eslint-disable-next-line react-hooks/exhaustive-deps
useEffect(()=>{load()},[token]);const checkout=async(planId:string)=>{setBusy(true);try{const result=await checkoutSubscription(token,planId);const provider=result.provider as {id?:string;amount?:number;currency?:string}|undefined;const order=result.order as {id?:string;amount?:number;currency?:string}|undefined;const razorpay=await importRazorpay();if(!razorpay||!result.keyId){toastGlobal("Payment provider is not configured");return}const options:RazorpayOptions={key:result.keyId,amount:order?.amount||provider?.amount,currency:order?.currency||provider?.currency||"INR",name:"NightBox",description:"Premium subscription",handler:async(response:RazorpayResponse)=>{await verifyPayment(token,result.subscriptionId,response);await load()}};if(result.mode==="subscription")options.subscription_id=provider?.id;else options.order_id=order?.id;new razorpay(options).open()}catch(error){toastGlobal(error instanceof Error?error.message:"Unable to start checkout")}finally{setBusy(false)}};const cancel=async()=>{if(!subscription)return;setBusy(true);try{await cancelSubscription(token,subscription.id);await load()}catch(error){toastGlobal(error instanceof Error?error.message:"Unable to cancel subscription")}finally{setBusy(false)}};const [now]=useState(()=>Date.now());const remainingDays=subscription?.expiresAt?Math.max(0,Math.ceil((Date.parse(subscription.expiresAt)-now)/86400000)):null;const active=(subscription?.status==="active"||subscription?.status==="cancelled")&&Boolean(subscription?.expiresAt);return <div className="card empty-state"><h2>{active?`${subscription?.name} plan ${subscription?.status}`:"Premium plans"}</h2>{active?<><p>{remainingDays===null?"Premium status is awaiting provider confirmation.":`${remainingDays} day(s) remaining until ${new Date(subscription!.expiresAt!).toLocaleDateString()}`.concat(subscription?.recurring?(subscription.renewsAt?` Renewal scheduled for ${new Date(subscription.renewsAt).toLocaleDateString()}.`:" Auto-renewal is enabled."):" This is a one-time plan; it will expire without renewal.")} {subscription?.allAdsRemoved?"All ads removed.":subscription?.videoAdsRemoved?"Video ads removed.":"Priority features are reserved for future configuration."}</p>{active&&subscription?.status==="active"&&<button className="btn btn-dark" disabled={busy} onClick={cancel}>{busy?"Updating…":"Cancel renewal"}</button>}</>:<><p>{plans.length?plans.map(plan=>`${plan.name}: ${plan.currency} ${(plan.price_minor/100).toFixed(2)}`).join(" · "):"No plans are currently available."}</p><div className="plan-actions">{plans.map(plan=><button key={plan.id} className="btn btn-primary" disabled={busy} onClick={()=>checkout(plan.id)}>Choose {plan.name}</button>)}</div></>}</div>}
function FileRows({files}:{files:FileItem[]}){return <div className="file-rows">{files.map(f=><div key={f.id}><span className="type-box" style={{background:f.color}}>{f.type}</span><span className="file-name"><b>{f.name}</b><small>{f.size} · {f.updated}</small></span><span><b>{f.views.toLocaleString()}</b><small>Views</small></span><span><b>{money(f.earned)}</b><small>Earned</small></span><Pill tone={f.status==="Live"?"green":"orange"}>{f.status}</Pill>{f.link&&<button onClick={()=>navigator.clipboard?.writeText(f.link||"")}>Share</button>}<button>•••</button></div>)}</div>}
function FilesTable({files,saveFiles,toast,token,go}:{files:FileItem[],saveFiles:(x:FileItem[])=>void,toast:(s:string)=>void,token:string,go:(p:string)=>void}){const [q,setQ]=useState("");const shown=files.filter(f=>f.name.toLowerCase().includes(q.toLowerCase()));const remove=async(id:string)=>{try{await deleteCreatorVideo(token,id);saveFiles(files.filter(x=>String(x.id)!==id));toast("File deleted")}catch(error){toast(error instanceof Error?error.message:"Unable to delete file")}};const share=async(file:FileItem)=>{let link=file.link;try{if(!link){const result=await createCreatorVideoLink(token,String(file.id));link=result.link.url;saveFiles(files.map(item=>item.id===file.id?{...item,link}:item))}await navigator.clipboard.writeText(link);toast("Share link copied")}catch(error){toast(error instanceof Error?error.message:"Unable to create share link")}};return <><AppTitle eyebrow="LIBRARY" title="My Files" action={<button className="btn btn-primary" onClick={()=>go("/user/upload")}>↑ Upload</button>}/><div className="toolbar"><div className="search">⌕<input value={q} onChange={e=>setQ(e.target.value)} placeholder="Search files…"/></div><select><option>All formats</option><option>Documents</option><option>Video</option></select><select><option>Recently updated</option><option>Most viewed</option></select><button className="icon-btn">▦</button></div><div className="card files-table"><div className="table-head"><span>FILE</span><span>STATUS</span><span>VIEWS</span><span>EARNED</span><span>UPDATED</span><span/></div>{shown.map(f=><div className="table-row" key={f.id}><span className="file-cell"><i className="type-box" style={{background:f.color}}>{f.type}</i><b>{f.name}<small>{f.size}</small></b></span><Pill tone={f.status==="Live"?"green":"orange"}>{f.status}</Pill><span>{f.views.toLocaleString()}</span><b>{money(f.earned)}</b><span>{f.updated}</span><button onClick={()=>share(f)}>{f.link?"Share":"Create link"}</button><button onClick={()=>remove(String(f.id))}>•••</button></div>)}</div></>}
function Analytics({token}:{token:string}){const [data,setData]=useState<{summary:{views:number;earningsMicros:number};countries:Array<{country:string;views:number;earningsMicros:number;cpmCents:number}>}|null>(null);useEffect(()=>{getCreatorAnalytics(token).then(setData).catch(()=>setData(null))},[token]);if(!data)return <><AppTitle eyebrow="PERFORMANCE" title="Analytics"/><div className="card empty-state"><h2>No analytics data yet</h2><p>Qualified views and country-level earnings will appear here after visitors complete the minimum watch time.</p></div></>;return <><AppTitle eyebrow="PERFORMANCE" title="Analytics"/><div className="metrics three"><Metric icon="◉" label="Eligible views" value={data.summary.views.toLocaleString()}/><Metric icon="$" label="Recorded earnings" value={money(data.summary.earningsMicros/1000000)}/><Metric icon="◎" label="Countries" value={String(data.countries.length)}/></div><div className="card files-table"><div className="table-head"><span>COUNTRY</span><span>VIEWS</span><span>CPM</span><span>EARNED</span></div>{data.countries.length?data.countries.map(row=><div className="table-row" key={row.country}><b>{row.country}</b><span>{row.views.toLocaleString()}</span><span>{money(row.cpmCents/100)}</span><b>{money(row.earningsMicros/1000000)}</b></div>):<p className="empty-copy">No country data yet.</p>}</div></>}

function LiveAdminLogin({go,setAuth,toast}:{go:(p:string)=>void,setAuth:(v:boolean)=>void,toast:(s:string)=>void}){const submit=async(e:React.FormEvent<HTMLFormElement>)=>{e.preventDefault();const data=new FormData(e.currentTarget);try{const result=await adminLogin(String(data.get("email")),String(data.get("password")));sessionStorage.setItem("nightbox-admin-token",result.token);sessionStorage.setItem("nightbox-admin","1");setAuth(true);toast("Secure admin session started");go("/admin/dashboard")}catch(error){toast(error instanceof Error?error.message:"Administrator login failed")}};return <div className="admin-login"><div className="admin-login-brand"><Brand dark go={go}/><Pill tone="orange">OPERATIONS CONSOLE</Pill></div><form onSubmit={submit}><span className="shield">◆</span><h1>Administrator access</h1><p>Use the administrator credentials configured on the backend.</p><label>Admin email<input name="email" required type="email" placeholder="admin@example.com"/></label><label>Password<input name="password" required type="password"/></label><button className="btn btn-primary btn-block">Enter command center →</button><small>Admin authentication is server-side and requires configured environment credentials.</small></form><button className="admin-back" onClick={()=>go("/")}>← Return to NightBox website</button></div>}

function AdminApp({route,go,auth,setAuth,toast}:{route:string,go:(p:string)=>void,auth:boolean,setAuth:(v:boolean)=>void,toast:(s:string)=>void}){if(route==="/admin/login"||!auth)return <LiveAdminLogin go={go} setAuth={setAuth} toast={toast}/>;return <div className="app-shell admin-app"><Sidebar nav={adminNav} route={route} go={go} admin/><div className="app-main"><Topbar go={go} admin/><div className="app-content">{route==="/admin/dashboard"&&<AdminDashboard/>}{route==="/admin/users"&&<LiveAdminUsers toast={toast}/>} {route==="/admin/files"&&<LiveAdminFiles toast={toast}/>} {route==="/admin/revenue"&&<><LiveAdminRevenue toast={toast}/><LiveAdminViews toast={toast}/><LiveAdminPlans toast={toast}/><LiveAdminPayments/><AdminPaymentActions toast={toast}/></>} {route==="/admin/withdrawals"&&<LiveAdminWithdrawals toast={toast}/>} {route==="/admin/reports"&&<LiveAdminReports toast={toast}/>} {route==="/admin/tickets"&&<LiveAdminTickets toast={toast}/>} {route==="/admin/events"&&<LiveAdminEvents toast={toast}/>} {route==="/admin/settings"&&<LiveAdminSettings/>}</div></div></div>}
function AdminDashboard(){const [status,setStatus]=useState("checking");const [overview,setOverview]=useState<{users:number;videos:number;qualifiedViews:number;earningsMicros:number;pendingWithdrawals:number}|null>(null);useEffect(()=>{const token=sessionStorage.getItem("nightbox-admin-token");Promise.all([getBackendHealth(),token?getAdminOverview(token):Promise.reject(new Error("Admin session expired"))]).then(([,data])=>{setStatus("connected");setOverview(data)}).catch(()=>setStatus("offline"))},[]);return <><AppTitle eyebrow="OPERATIONS" title="Command Center"/><div className="card empty-state"><h2>Backend connection</h2><p>{status==="connected"?"The local NightBox backend and admin data are connected.":status==="offline"?"The local backend or admin session is not reachable.":"Checking the local backend…"}</p><Pill tone={status==="connected"?"green":"orange"}>{status}</Pill></div><div className="metrics"><Metric icon="♙" label="Creators" value={overview?overview.users.toLocaleString():"—"}/><Metric icon="▱" label="Stored videos" value={overview?overview.videos.toLocaleString():"—"}/><Metric icon="◉" label="Qualified views" value={overview?overview.qualifiedViews.toLocaleString():"—"}/><Metric icon="$" label="Recorded earnings" value={overview?money(overview.earningsMicros/1000000):"—"}/></div><div className="card empty-state"><h2>Pending withdrawals</h2><p>{overview?`${overview.pendingWithdrawals} request(s) require review.`:"Waiting for authenticated admin data."}</p></div></>}
function DataTable({headers,rows,actions}:{headers:string[],rows:(string|React.ReactNode)[][],actions?:boolean}){return <div className="card admin-table"><div className="admin-table-head">{headers.map(h=><span key={h}>{h}</span>)}{actions&&<span/>}</div>{rows.map((r,i)=><div className="admin-table-row" key={i}>{r.map((x,j)=><span key={j}>{x}</span>)}{actions&&<button>•••</button>}</div>)}</div>}
function LiveAdminUsers({toast}:{toast:(s:string)=>void}){const [rows,setRows]=useState<Array<{id:string;email:string;role:string;status:string;telegramUserId:string|null;createdAt:string}>>([]);const [q,setQ]=useState("");const [error,setError]=useState("");const load=()=>{const token=sessionStorage.getItem("nightbox-admin-token");if(!token){setError("Admin session expired");return}getAdminUsers(token).then(x=>setRows(x.users)).catch(e=>setError(e instanceof Error?e.message:"Unable to load users"))};
// eslint-disable-next-line react-hooks/set-state-in-effect
useEffect(load,[]);const toggle=async(row:AdminUser)=>{const token=sessionStorage.getItem("nightbox-admin-token");if(!token)return;try{await updateAdminUser(token,row.id,row.status==="active"?"suspended":"active");toast(`Creator ${row.status==="active"?"suspended":"activated"}`);load()}catch(error){toast(error instanceof Error?error.message:"Unable to update creator")}};const shown=rows.filter(row=>`${row.email} ${row.id}`.toLowerCase().includes(q.toLowerCase()));return <><AppTitle eyebrow="IDENTITY & ACCESS" title="Users" action={<button className="btn btn-dark" onClick={load}>Refresh</button>}/><div className="admin-filters"><div className="search">⌕<input value={q} onChange={e=>setQ(e.target.value)} placeholder="Search email or user ID…"/></div></div>{error?<div className="card empty-state"><h2>Unable to load users</h2><p>{error}</p></div>:<DataTable headers={["USER","ROLE","TELEGRAM","CREATED","STATUS","ACTION"]} actions rows={shown.map(row=>[<span className="person" key={row.id}><i>{row.email.slice(0,2).toUpperCase()}</i><b>{row.email}<small>{row.id}</small></b></span>,row.role,row.telegramUserId||"Not connected",new Date(row.createdAt).toLocaleDateString(),<Pill key="status" tone={row.status==="active"?"green":"orange"}>{row.status}</Pill>,<button key={row.id} onClick={()=>toggle(row)}>{row.status==="active"?"Suspend":"Activate"}</button>])}/>}</>}
function LiveAdminPlans({toast}:{toast:(s:string)=>void}){const [plans,setPlans]=useState<Array<{id:string;name:string;priceMinor:number;currency:string;durationDays:number;recurring:number;active:number}>>([]);const load=()=>{const token=sessionStorage.getItem("nightbox-admin-token");if(token)getAdminPlans(token).then(x=>setPlans(x.plans)).catch(()=>setPlans([]))};useEffect(load,[]);const save=async(plan:{id:string;name:string},input:HTMLInputElement,active:HTMLInputElement)=>{const token=sessionStorage.getItem("nightbox-admin-token");if(!token)return;try{await updateAdminPlan(token,plan.id,Math.round(Number(input.value)*100),active.checked?1:0);toast(`${plan.name} plan updated`);load()}catch(error){toast(error instanceof Error?error.message:"Unable to update plan")}};return <><AppTitle eyebrow="PREMIUM" title="Subscription plans"/><DataTable headers={["PLAN","PRICE (INR)","RECURRING","ACTIVE","ACTION"]} rows={plans.map(plan=>[plan.name,<input key={plan.id} type="number" min="0" step="0.01" defaultValue={(plan.priceMinor/100).toFixed(2)}/>,plan.recurring?"Yes":"No",<input key={`active-${plan.id}`} type="checkbox" defaultChecked={Boolean(plan.active)}/>,<button key={`save-${plan.id}`} onClick={event=>{const cell=event.currentTarget.parentElement;const input=cell?.children[1] as HTMLInputElement;const active=cell?.children[3] as HTMLInputElement;if(input&&active)save(plan,input,active)}}>Save</button>])}/></>}
function LiveAdminFiles({toast}:{toast:(s:string)=>void}){const [rows,setRows]=useState<Array<{id:string;title:string;status:string;ownerId:string|null;createdAt:string;eligibleViews:number}>>([]);const [error,setError]=useState("");const load=()=>{const token=sessionStorage.getItem("nightbox-admin-token");if(!token){setError("Admin session expired");return}getAdminVideos(token).then(x=>setRows(x.videos)).catch(e=>setError(e instanceof Error?e.message:"Unable to load videos"))};
// eslint-disable-next-line react-hooks/set-state-in-effect
useEffect(load,[]);const remove=async(id:string)=>{const token=sessionStorage.getItem("nightbox-admin-token");if(!token)return;try{await deleteAdminVideo(token,id);toast("Video deleted");load()}catch(error){toast(error instanceof Error?error.message:"Unable to delete video")}};return <><AppTitle eyebrow="CONTENT OPERATIONS" title="File moderation" action={<button className="btn btn-dark" onClick={load}>Refresh queue</button>}/>{error?<div className="card empty-state"><h2>Unable to load files</h2><p>{error}</p></div>:<DataTable headers={["FILE","OWNER ID","VIEWS","STATUS","CREATED","ACTION"]} rows={rows.map(row=>[<b key={row.id}>{row.title}<small>{row.id}</small></b>,row.ownerId||"Bot upload",row.eligibleViews.toLocaleString(),<Pill key="status" tone={row.status==="ready"?"green":"orange"}>{row.status}</Pill>,new Date(row.createdAt).toLocaleDateString(),<button key={`delete-${row.id}`} onClick={()=>remove(row.id)}>Delete</button>])}/>}</>}
function LiveAdminRevenue({toast}:{toast:(s:string)=>void}){const [rates,setRates]=useState<Array<{country:string;cpmCents:number;active:number}>>([]);const [rules,setRules]=useState({eligiblePercent:100,maxViewsPerViewer24h:1,minimumWatchSeconds:5});const [error,setError]=useState("");const [newCountry,setNewCountry]=useState("");const [newCpm,setNewCpm]=useState("");const load=()=>{const token=sessionStorage.getItem("nightbox-admin-token");if(!token){setError("Admin session expired");return}Promise.all([getAdminCpm(token),getAdminViewRules(token)]).then(([cpm,viewRules])=>{setRates(cpm.rates);setRules(viewRules.rules)}).catch(e=>setError(e instanceof Error?e.message:"Unable to load revenue controls"))};
// eslint-disable-next-line react-hooks/set-state-in-effect
useEffect(load,[]);const save=async(country:string,value:string)=>{const token=sessionStorage.getItem("nightbox-admin-token");if(!token)return;try{await updateAdminCpm(token,country,Math.round(Number(value)*100));toast(`${country} CPM updated`);load()}catch(error){toast(error instanceof Error?error.message:"Unable to update CPM")}};const add=async(e:React.FormEvent)=>{e.preventDefault();const country=newCountry.trim().toUpperCase();const amount=Number(newCpm);if(!/^[A-Z]{2}$/.test(country)||!Number.isFinite(amount)||amount<0){toast("Use a valid ISO country code and CPM");return}await save(country,String(amount));setNewCountry("");setNewCpm("")};const saveRules=async(e:React.FormEvent)=>{e.preventDefault();const token=sessionStorage.getItem("nightbox-admin-token");if(!token)return;try{await updateAdminViewRules(token,rules);toast("View earning rules updated");load()}catch(error){toast(error instanceof Error?error.message:"Unable to update view rules")}};return <><AppTitle eyebrow="MONETIZATION" title="Revenue controls"/>{error?<div className="card empty-state"><p>{error}</p></div>:<><form className="card compact-form" onSubmit={saveRules}><h2>Eligible-view rules</h2><div className="three"><label>Eligible percentage<input type="number" min="0" max="100" value={rules.eligiblePercent} onChange={e=>setRules({...rules,eligiblePercent:Number(e.target.value)})}/></label><label>Views per viewer / 24h<input type="number" min="1" value={rules.maxViewsPerViewer24h} onChange={e=>setRules({...rules,maxViewsPerViewer24h:Number(e.target.value)})}/></label><label>Minimum seconds<input type="number" min="5" value={rules.minimumWatchSeconds} onChange={e=>setRules({...rules,minimumWatchSeconds:Number(e.target.value)})}/></label></div><button className="btn btn-primary">Save earning rules</button></form><div className="card empty-state"><h2>Country CPM rates</h2><p>Only server-recorded eligible views create earnings. CPM is applied and locked at qualification time.</p><form className="three" onSubmit={add}><label>Country code<input required maxLength={2} value={newCountry} onChange={e=>setNewCountry(e.target.value)} placeholder="IN"/></label><label>CPM (USD)<input required min="0" step="0.01" type="number" value={newCpm} onChange={e=>setNewCpm(e.target.value)} placeholder="10.00"/></label><button className="btn btn-dark">Add or update country</button></form></div><DataTable headers={["COUNTRY","CPM USD","STATUS","ACTION"]} rows={rates.map(rate=>[rate.country,<input key={rate.country} type="number" min="0" step="0.01" defaultValue={(rate.cpmCents/100).toFixed(2)}/>,<Pill key={`status-${rate.country}`} tone={rate.active?"green":"orange"}>{rate.active?"Active":"Disabled"}</Pill>,<button key={`save-${rate.country}`} onClick={event=>{const input=(event.currentTarget.parentElement?.children[1] as HTMLInputElement);save(rate.country,input.value)}}>Save</button>])}/></>}</>}
function LiveAdminWithdrawals({toast}:{toast:(s:string)=>void}){const [rows,setRows]=useState<Array<{id:string;creatorId:string;email:string;amountMicros:number;currency:string;method:string;status:string;requestedAt:string}>>([]);const [error,setError]=useState("");const load=()=>{const token=sessionStorage.getItem("nightbox-admin-token");if(!token){setError("Admin session expired");return}getAdminWithdrawals(token).then(x=>setRows(x.withdrawals)).catch(e=>setError(e instanceof Error?e.message:"Unable to load withdrawals"))};
// eslint-disable-next-line react-hooks/set-state-in-effect
useEffect(load,[]);const update=async(id:string,status:"approved"|"paid"|"rejected")=>{const token=sessionStorage.getItem("nightbox-admin-token");if(!token)return;try{await updateAdminWithdrawal(token,id,status);toast(`Withdrawal ${status}`);load()}catch(error){toast(error instanceof Error?error.message:"Unable to update withdrawal")}};return <><AppTitle eyebrow="PAYOUT OPERATIONS" title="Withdrawals" action={<button className="btn btn-dark" onClick={load}>Refresh</button>}/>{error?<div className="card empty-state"><p>{error}</p></div>:<DataTable headers={["CREATOR","AMOUNT","METHOD","STATUS","REQUESTED","ACTION"]} rows={rows.map(row=>[row.email,money(row.amountMicros/1000000),row.method,row.status,new Date(row.requestedAt).toLocaleDateString(),row.status==="pending"?<Fragment key={row.id}><button onClick={()=>update(row.id,"approved")}>Approve</button><button onClick={()=>update(row.id,"rejected")}>Reject</button></Fragment>:row.status==="approved"?<button onClick={()=>update(row.id,"paid")}>Mark paid</button>:"-"])}/>}</>}
function LiveAdminPayments(){const [subscriptions,setSubscriptions]=useState<AdminSubscription[]>([]);const [payments,setPayments]=useState<AdminPayment[]>([]);const [error,setError]=useState("");
// eslint-disable-next-line react-hooks/set-state-in-effect
useEffect(()=>{const token=sessionStorage.getItem("nightbox-admin-token");if(!token){setError("Admin session expired");return}Promise.all([getAdminSubscriptions(token),getAdminPayments(token)]).then(([s,p])=>{setSubscriptions(s.subscriptions);setPayments(p.payments)}).catch(e=>setError(e instanceof Error?e.message:"Unable to load payment records"))},[]);return <><AppTitle eyebrow="PAYMENTS" title="Subscription activity"/>{error?<div className="card empty-state"><p>{error}</p></div>:<><DataTable headers={["PLAN","STATUS","STARTED","EXPIRES","CANCELLED"]} rows={subscriptions.map(row=>[row.plan_id,row.status,row.started_at?new Date(row.started_at).toLocaleDateString():"-",row.expires_at?new Date(row.expires_at).toLocaleDateString():"-",row.cancelled_at?new Date(row.cancelled_at).toLocaleDateString():"-"])}/><div className="card empty-state"><h2>Payment ledger</h2><p>{payments.length} provider record(s) returned by the backend.</p>{payments.slice(0,10).map(row=><div className="table-row" key={row.id}><span>{row.provider_payment_id||row.id.slice(0,8)}</span><span>{row.currency} {(row.amount_minor/100).toFixed(2)}</span><Pill tone={row.status==="paid"?"green":"orange"}>{row.status}</Pill><span>{new Date(row.created_at).toLocaleDateString()}</span></div>)}</div></>}</>}
function NotFound({go}:{go:(p:string)=>void}){return <section className="not-found"><b>404</b><h1>This NightLink drifted into space.</h1><p>The page may have moved, expired or never existed.</p><button className="btn btn-primary" onClick={()=>go("/")}>Return home</button></section>}
